					sql.add("alter table " + getTableName() + " drop index `" + myIndexName + "`");
					break;
				case H2_EMBEDDED:
					sql.add("drop index " + myIndexName);
					break;
				case DERBY_EMBEDDED:
					sql.add("alter table " + getTableName() + " drop constraint " + myIndexName);
					break;
